<script setup lang="ts">
import { ref, reactive, computed } from 'vue'
import { Refresh, Connection } from '@element-plus/icons-vue'
import { api, put, post, errorText } from '../api'
import { useLoad } from '../composables'
import { ElMessage, ElMessageBox } from 'element-plus'
const health=ref<any>(null),saving=ref(false),syncing=ref(false),formError=ref(''),loaded=ref(false),originalLiveness=ref(false)
const form=reactive({testMode:false,livenessEnabled:true,recognitionThreshold:0.5,candidateMargin:0.08,calibrationConfirmed:false})
const {loading,error,load}=useLoad(async()=>{loaded.value=false;const [s,h]=await Promise.all([api('/settings'),api('/system/health')]);Object.assign(form,{testMode:!!s.testMode,livenessEnabled:s.livenessEnabled,recognitionThreshold:s.recognitionThreshold,candidateMargin:s.candidateMargin,calibrationConfirmed:s.calibrationConfirmed});originalLiveness.value=s.livenessEnabled;health.value=h;loaded.value=true})
function invalidateCalibration(){form.calibrationConfirmed=false}
function state(v:any){if(v===true||v==='UP'||v==='READY'||v==='OK'||v==='HEALTHY')return '正常';if(v===false||v==='DOWN'||v==='UNAVAILABLE')return '不可用';if(typeof v==='object'&&v)return v.status||'待确认';return v||'未知'}
const healthCards=computed(()=>[{label:'业务数据库',value:state(health.value?.database)},{label:'算法服务',value:state(health.value?.algorithm)},{label:'识别模型',value:state(health.value?.model)},{label:'人员库同步',value:health.value?health.value.gallerySynced?'已同步':'待同步':'未知'}])
async function save(){if(!loaded.value)return;try{if(form.livenessEnabled!==originalLiveness.value)await ElMessageBox.confirm('动作检测开关变更将立即使未完成打卡会话失效，公共设备需要重新开始。','确认调整动作检测',{confirmButtonText:'保存设置',cancelButtonText:'取消',type:'warning'});saving.value=true;formError.value='';await put('/settings',form);ElMessage.success('识别设置已保存');await load()}catch(e){if(e!=='cancel'&&e!=='close')formError.value=errorText(e)}finally{saving.value=false}}
async function sync(){syncing.value=true;try{await post('/system/sync-gallery');ElMessage.success('人员库已同步');await load()}catch(e){ElMessage.error(errorText(e))}finally{syncing.value=false}}
</script>
<template><div class="page-head"><div><h1>系统运行</h1></div><div class="head-actions"><router-link to="/diagnostics"><el-button>识别诊断</el-button></router-link><el-button :icon="Refresh" :loading="loading" @click="load">刷新状态</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="panel" v-loading="loading"><div class="panel-head"><div><h2>服务状态</h2></div><el-button :icon="Connection" :loading="syncing" @click="sync">重新同步人员库</el-button></div><div class="health-grid"><div v-for="item in healthCards" :key="item.label" class="health-card">{{item.label}}<strong>{{item.value}}</strong></div></div><div class="help-text">人员库版本：{{health?.galleryVersion??'—'}}<br>{{health?.detail||'人员库未同步时暂不能打卡，可点击重新同步。'}}</div></div><div class="panel section-gap"><div class="panel-head"><div><h2>识别与动作检测</h2><p>使用独立样本校准参数后，确认并保存。</p></div></div><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><div class="setting-row"><div><h3>全天测试打卡</h3><p>全天可测试，不受请假限制。测试记录单独保存，不计入正式报表。</p></div><el-switch v-model="form.testMode" :disabled="!loaded"/></div><div class="setting-row"><div><h3>随机动作检测</h3><p>打卡时按随机顺序完成眨眼和张嘴。</p></div><el-switch v-model="form.livenessEnabled" :disabled="!loaded" active-text="开启" inactive-text="关闭"/></div><div class="rule-hint section-gap">{{form.livenessEnabled?'开启后，打卡需完成动作验证。':'关闭后仍需通过人脸识别，动作结果记为「跳过」。'}}</div><el-alert v-if="loaded && !form.calibrationConfirmed" title="当前参数尚未确认校准；按此状态保存将关闭公共打卡。请完成独立样本校准后勾选下方确认项。" type="warning" show-icon :closable="false" class="section-gap"/><el-form v-if="loaded" label-position="top" class="compact-form section-gap"><div class="form-grid"><el-form-item label="识别相似度阈值"><el-input-number v-model="form.recognitionThreshold" @change="invalidateCalibration" :min="0.1" :max="1" :step="0.01" :precision="3" :disabled="!loaded"/><div class="help-text">第一候选必须达到该阈值。</div></el-form-item><el-form-item label="候选最小分差"><el-input-number v-model="form.candidateMargin" @change="invalidateCalibration" :min="0" :max="1" :step="0.01" :precision="3" :disabled="!loaded"/><div class="help-text">前两名候选的最低分差；仅有一人时不使用。</div></el-form-item></div><el-form-item><el-checkbox v-model="form.calibrationConfirmed" :disabled="!loaded">已完成独立样本校准，并保留校准记录</el-checkbox></el-form-item><el-button type="primary" :loading="saving" :disabled="!loaded" @click="save">保存识别设置</el-button></el-form></div></template>
